import { Header } from './dist/esm/header.js'
import { encode } from './dist/esm/large-numbers.js'

export default async function testCase(input) {
  const { exSize, gexSize, blockSize } = input

  const buf = Buffer.alloc(512, 0)
  buf.write('ustar\x0000', 257, 8, 'utf8')
  buf[156] = 48 // '0' char code

  if (blockSize !== undefined && blockSize >= 0) {
    const octal = String(blockSize).padStart(11, '0').slice(-11) + ' \x00'
    buf.write(octal, 124, 12, 'ascii')
  } else if (blockSize !== undefined && blockSize < 0) {
    encode(blockSize, buf.subarray(124, 136))
  }

  const ex = exSize !== undefined ? { size: exSize } : undefined
  const gex = gexSize !== undefined ? { size: gexSize } : undefined

  const h = new Header(buf, 0, ex, gex)
  return h.size
}

import { Header } from './dist/esm/header.js'

